import requests

def create_thing(name, category):
  url = "https://things.mimo.dev/api/things"
  data = {
    "name": name,
    "category": category
  }
  response = requests.post(url, json=data)
  result = response.json()
  return result["id"]

import requests

def load_pokemon(pokemon_id):
  url = f"https://pokedex.mimo.dev/api/pokemon/{pokemon_id}"
  try:
    response = requests.get(url)
    response.raise_for_status()
    data = response.json()
    return data["name"]
  except requests.exceptions.HTTPError:
    return "Pokémon not found"

import requests

def load_characters():
  url = "https://rickandmorty.mimo.dev/api/character"
  try:
    response = requests.get(url)
    response.raise_for_status()
    data = response.json()
    return data["results"]
  except requests.exceptions.HTTPError:
    return []
